style.css:
@-moz-document domain("discord.com") {
/* Arkaplan görseli */
  body {
    background: url('https://static1.moviewebimages.com/wordpress/wp-content/uploads/2024/07/who-is-the-ice-truck-killer-in-dexter-unpacking-the-show-s-best-villain.jpg') no-repeat center center fixed;
    background-size: cover;
  }

  /* Buton Kenarlarına Neon Kırmızı Efekti */
  button {
    background-color: rgba(0, 0, 0, 0.5) !important; /* Buton arka planını şeffaf yap */
    border: 2px solid #ff0000 !important; /* Neon kırmızı kenar */
    color: white !important; /* Buton yazıları beyaz */
    text-shadow: 0 0 5px #ff0000, 0 0 10px #ff0000, 0 0 20px #ff0000, 0 0 40px #ff0000 !important; /* Neon ışık efekti */
  }

  /* Yazılar ve Mesajlar */
  .content-2zF1tY, .title-3A7U1n, .messageContent-2qWWX8 {
    color: white !important; /* Yazı rengi beyaz */
    opacity: 0.9 !important; /* Yazı şeffaflığı */
  }

  /* Linklere Neon Kırmızı Efekti */
  a {
    color: white !important; /* Link rengi beyaz */
    text-shadow: 0 0 5px #ff0000, 0 0 10px #ff0000, 0 0 20px #ff0000, 0 0 40px #ff0000 !important; /* Neon ışık efekti */
  }
}
